sys_transform_script.script:
(function runTransformScript(source, map, log, target) {
  var targetGR = new GlideRecord('x_erace_sbom_sboms');
  targetGR.query();
  while (targetGR.next()) {
    // Find the matching record in the reference table
    var refGR = new GlideRecord('x_erace_sbom_application_modules_summary');
    refGR.addQuery("sbom_id", targetGR.getValue("sys_id"));
    refGR.query();

    if (refGR.next()) {
      // Set the reference field to the sys_id of the matching record
      targetGR.unique_application_module = refGR.getValue("sys_id");
      targetGR.update();
    }
  }

})(source, map, log, target);
